    ht = -8.0 if t - _st['t2'] < 6.0 else 0.0
    steer = 1.5 * (h - ht)
    if steer > 30.0:
        steer = 30.0
    if steer < -30.0:
        steer = -30.0
    return (steer, -0.8, 180.0)

